    def parity(name):
        resp = (out.get(name) or {}).get('response')
        if not resp:
            return {'missing': True}
        try:
            term = copy.deepcopy(resp.get('termination') or {'class': 'success'})
            env = {'schemaFamily': 'opensip.product.envelope', 'schemaMajor': 3, 'kind': 'query', 'requestId': RID, 'projectId': project,
